# Congratulations - you've finished Python L1!
# Here's a small program that uses almost everything from the course.
# Read through it, run it, then try modifying it.

import math

class Shape:
    def __init__(self, name):
        self.name = name

    def area(self):
        return 0

    def describe(self):
        a = self.area()
        return f"{self.name}: area = {a:.2f}"

class Circle(Shape):
    def __init__(self, radius):
        super().__init__("Circle")
        self.radius = radius

    def area(self):
        return math.pi * self.radius ** 2

class Rectangle(Shape):
    def __init__(self, width, height):
        super().__init__("Rectangle")
        self.width  = width
        self.height = height

    def area(self):
        return self.width * self.height


shapes = [Circle(5), Rectangle(4, 6), Circle(3), Rectangle(10, 2)]

print("All shapes:")
for shape in shapes:
    print(" ", shape.describe())

areas = [s.area() for s in shapes]
print(f"\nLargest area: {max(areas):.2f}")
print(f"Total area:   {sum(areas):.2f}")
